def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strongest_live_prev = 0.0
    cindy_alive = False
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            if agent_id == 'Cindy':
                cindy_alive = True
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid > strongest_live_prev:
                    strongest_live_prev = bid

    alive_count = len(alive)
    if alive_count == 0:
        return float(min(budget, 18.0))

    units = int(supply // WATER_REQ)
    scarcity = units < (alive_count + 1)
    severe_scarcity = units <= max(0, alive_count - 1)

    urgent = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if urgent:
        if cindy_alive:
            bid = 58.0
        else:
            bid = 52.0 if scarcity else 44.0
        if strongest_live_prev > 0:
            bid = max(bid, min(64.0, strongest_live_prev + 2.0))
        return float(min(budget, bid))

    if severe_scarcity:
        if strongest_live_prev >= 100:
            bid = 12.0 if hp > 5 else 46.0
        elif strongest_live_prev >= 70:
            bid = 24.0 if hp > 5 else 49.0
        else:
            bid = 34.0 if pressured else 22.0
    elif scarcity:
        if strongest_live_prev >= 100:
            bid = 14.0 if hp > 6 else 42.0
        elif strongest_live_prev >= 60:
            bid = 28.0 if hp > 5 else 40.0
        else:
            bid = 30.0 if pressured else 20.0
    else:
        bid = 16.0 if hp > 5 else 26.0

    dangerous_rivals = 0
    for agent_id, opp in alive:
        ob = opp.get('budget', 0)
        ohp = opp.get('hp', 0)
        prev = opp.get('previous_trace', {})
        pbid = prev.get('bid') if prev else None
        if ob >= 40 and ohp <= 4:
            dangerous_rivals += 1
        elif pbid is not None and float(pbid) >= 60 and ob >= 20:
            dangerous_rivals += 1

    if dangerous_rivals >= 2 and pressured:
        bid += 8.0
    elif dangerous_rivals == 0 and hp >= 6:
        bid -= 4.0

    if cindy_alive and strongest_live_prev >= 110 and hp >= 5:
        bid = min(bid, 18.0)

    bid = max(0.0, min(float(budget), bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate pressure signal
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Baseline bid: aim mid to win occasionally without burning budget
    # If supply is higher, competition likely increases; bid a bit more.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Determine urgency from hp and no_water_days
    urgency = 0.0
    if hp <= 2.0:
        urgency += 0.9
    elif hp <= 4.0:
        urgency += 0.55
    else:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 0.35
    elif no_water_days == 1:
        urgency += 0.15

    # Use yesterday's highest bid as a proxy for aggressive opponents.
    # If someone already bid very high, avoid matching exactly; instead slightly undercut.
    target = None
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Cindy-like aggression: don't fully mirror; choose a defensive bid.
        target = DAILY_SALARY * (0.45 + 0.25 * supply_ratio) + urgency * DAILY_SALARY * 0.2
        # Undercut relative to yesterday peak
        target = min(target, highest_prev_bid - 5.0)
    else:
        # Moderate pressure: bid around mid-high based on urgency and supply.
        target = DAILY_SALARY * (0.5 + 0.2 * supply_ratio) + urgency * DAILY_SALARY * 0.25

    # If budget is low, scale down but still react to low hp.
    if budget <= DAILY_SALARY * 0.4:
        target = min(target, budget * (0.65 if hp > 2.0 else 0.9))

    # Ensure non-negative and within budget
    target = max(0.0, float(target))
    bid = min(budget, target)

    # If my hp is critically low, prioritize survival.
    if hp <= 1.5:
        bid = min(budget, max(bid, DAILY_SALARY * 0.9))

    # Small strategic oscillation by day to avoid ties/predictability
    if day % 2 == 0:
        bid *= (1.03)
    else:
        bid *= (0.98)

    bid = max(0.0, min(budget, float(bid)))
    return float(bid)

